mapper.sql:
SELECT id, tenant_id, site_id, order_no, title, equipment_id, description,
       priority, status, assignee_user_id, team_id, version, due_at, completed_at,
       created_by, created_at, updated_at
FROM work_orders
WHERE tenant_id = #{tenantId}

    AND status = #{query.status}


    AND priority = #{query.priority}


    AND equipment_id = #{query.equipmentId}


    AND assignee_user_id = #{query.assigneeUserId}



    AND (order_no LIKE CONCAT('%', #{keyword}, '%')
         OR title LIKE CONCAT('%', #{keyword}, '%'))

mapper.select:

AND status IN ('PENDING', 'IN_PROGRESS', 'AWAITING_ACCEPTANCE')
AND due_at < #{asOf}
ORDER BY due_at ASC, id ASC

mapper.update:
UPDATE work_orders
SET assignee_user_id = #{assigneeUserId}, version = version + 1
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND status = 'PENDING'
  AND assignee_user_id IS NULL

UPDATE work_orders
SET status = 'IN_PROGRESS', version = version + 1
WHERE tenant_id = #{tenantId}
AND id = #{id}
AND status = 'PENDING'
AND assignee_user_id = #{assigneeUserId}

UPDATE work_orders
SET status = 'AWAITING_ACCEPTANCE', version = version + 1
WHERE tenant_id = #{tenantId}
AND id = #{id}
AND status = 'IN_PROGRESS'
AND assignee_user_id = #{assigneeUserId}

UPDATE work_orders
SET status = 'COMPLETED', version = version + 1,
    completed_at = CURRENT_TIMESTAMP(3)
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND status = 'AWAITING_ACCEPTANCE'
  AND assignee_user_id != #{actorUserId}

UPDATE work_orders
SET status = 'IN_PROGRESS', version = version + 1
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND status = 'AWAITING_ACCEPTANCE'
  AND assignee_user_id != #{actorUserId}
